import openpyxl
wb = openpyxl.load_workbook('3_59511_answer_inconsistent_color_9836_input.xlsx')
ws = wb['Sheet1']
def color_info(c):
    try:
        return c.fill.fgColor.rgb
    except Exception:
        return 'theme:'+str(c.fill.fgColor.theme) if c.fill.fgColor else 'none'
for row in ws.iter_rows(min_row=1, max_row=13, min_col=1, max_col=6):
    for c in row:
        ft = c.fill.fill_type
        if ft != 'solid' and c.value is None:
            continue
        print(c.coordinate, repr(c.value), 'fill_type=', ft, 'fg=', color_info(c))
